import { useState } from 'react'

import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import type { TodoViewModel } from '../../application/TodoViewModel'

type TodoItemProps = {
  todo: TodoViewModel
  onComplete: (id: string) => Promise<'completed' | 'already-completed'>
}

export const TodoItem = ({ todo, onComplete }: TodoItemProps) => {
  const [message, setMessage] = useState<string | null>(null)

  const complete = async () => {
    setMessage(null)
    try {
      const outcome = await onComplete(todo.id)
      if (outcome === 'already-completed') setMessage('This todo is already completed.')
    } catch {
      setMessage('The todo could not be completed.')
    }
  }

  return (
    <li>
      {todo.title}
      {todo.status === 'done' ? ' (done)' : null}{' '}
      <button type="button" onClick={complete}>
        Complete
      </button>
      {message ? <ErrorMessage>{message}</ErrorMessage> : null}
    </li>
  )
}
